import argparse
import datetime
import re
import subprocess
import sys

import yaml
from pathspec import PathSpec

HEADER_COMMENT_PATTERNS = {
    ".java": re.compile(r"/\*.*?\*/", re.DOTALL),
    ".xml": re.compile(r"<!--.*?-->", re.DOTALL),
}

YEARS_PATTERN = re.compile(r"(Copyright \(c\) )(\d{4})(?:, (\d{4}))?(?= )")


def load_ignore_spec(config_path):
    with open(config_path, "r", encoding="utf-8") as stream:
        config = yaml.safe_load(stream)
    return PathSpec.from_lines("gitwildmatch", config.get("ignore") or [])


def tracked_files():
    output = subprocess.run(
        ["git", "ls-files", "-z", "*.java", "*.xml"], check=True, capture_output=True, text=True
    ).stdout
    return [path for path in output.split("\0") if path]


def updated_years(match, year):
    first = int(match.group(2))
    last = int(match.group(3)) if match.group(3) else first
    if last == year and (first < year or match.group(3) is None):
        return None
    if first >= year:
        return str(year)
    return "{}, {}".format(first, year)


def update_file(path, year, dry_run):
    comment_pattern = HEADER_COMMENT_PATTERNS.get(path[path.rfind("."):])
    if comment_pattern is None:
        return False

    with open(path, "r", encoding="utf-8", newline="") as stream:
        content = stream.read()

    header = comment_pattern.search(content)
    if header is None:
        return False

    years = YEARS_PATTERN.search(content, header.start(), header.end())
    if years is None:
        return False

    new_years = updated_years(years, year)
    if new_years is None:
        return False

    content = content[: years.start(2)] + new_years + content[years.end(0):]
    if not dry_run:
        with open(path, "w", encoding="utf-8", newline="") as stream:
            stream.write(content)
    return True


def main():
    parser = argparse.ArgumentParser(description="Update the copyright year of Java and XML file headers")
    parser.add_argument("-c", "--config", default=".github/copyright-config.yml", help="copyright-check config file")
    parser.add_argument("-y", "--year", type=int, default=datetime.date.today().year, help="target year")
    parser.add_argument("-n", "--dry-run", action="store_true", help="only list the files that would change")
    parser.add_argument("files", nargs="*", help="files to update (default: all tracked Java and XML files)")
    args = parser.parse_args()

    ignore_spec = load_ignore_spec(args.config)
    files = args.files or tracked_files()

    updated = 0
    for path in files:
        if ignore_spec.match_file(path):
            continue
        try:
            if update_file(path, args.year, args.dry_run):
                updated += 1
                print(path)
        except (OSError, UnicodeDecodeError) as error:
            print("Skipping {}: {}".format(path, error), file=sys.stderr)

    print("{} {} file(s)".format("Would update" if args.dry_run else "Updated", updated), file=sys.stderr)


if __name__ == "__main__":
    main()
